#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        // x>=1, y>=1, x+y<=n
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: move target to position 0
        if(pos>0){
            // op(pos, n-pos): part3=[pos..n-1], part2=empty(if x+y=n) or [pos..n-1-y..], part1=[0..pos-1]
            // if x=pos, y=n-pos, x+y=n: result=[a_pos..a_{n-1}, a_0..a_{pos-1}]
            // target at pos goes to position 0
            if(pos + (n-pos) <= n){ // always true, =n
                doOp(pos, n-pos);
                pos=0;
            }
        }

        // Now target is at position 0. Move it to position 'placed'.
        if(placed==0) continue;
        // op(1, n-placed): part3=[placed..n-1], part2=[1..placed-1], part1=[0]
        // result: [a_placed..a_{n-1}, a_1..a_{placed-1}, a_0]
        // target (a_0) goes to position n-1. Not helpful.

        // op(1, placed): part3=[n-placed..n-1], part2=[1..n-placed-1], part1=[0]
        // result: [a_{n-placed}..a_{n-1}, a_1..a_{n-placed-1}, a_0]
        // target goes to last position n-1
        // Then op(placed, n-placed): rotates to put last n-placed elems first... 
        // Actually: op with x=n-placed, y=placed gives [last placed, middle, first n-placed]
        // Hmm. Let me just use: target at 0, want at placed.
        // op(1, n-placed) puts target at end. Then op(placed+1, n-placed-1)... 
        // Simpler: op(1, n-1-placed) if valid
        doOp(1, n-1-placed>=1 ? n-1-placed : 1);
        // Just recheck
        for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos!=placed){ doOp(n-pos, pos-placed); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
